use notifyredirect_core::*;use notifyredirect_storage::*;use chrono::{Utc,Duration};
fn setup()->(Store,Settings,Message){let now=Utc::now();let s=Store::open_memory().unwrap();let mut c=Settings::default();c.rules.mode=Mode::Always;c.rules.app_ids.push("app".into());c.channels.push(ChannelConfig{id:"c".into(),kind:ChannelKind::Feishu,name:"test".into(),enabled:true});(s,c,Message::new("key","app","App","title","body",now))}
#[test] fn deduplicates_and_updates_only_unattempted_messages(){let(mut s,c,m)=setup();assert_eq!(s.ingest(&m,false,&c,true,m.occurred_at).unwrap(),Observation::New);assert_eq!(s.ingest(&m,false,&c,true,m.occurred_at).unwrap(),Observation::Duplicate);let mut changed=m.clone();changed.body="new".into();changed.id=id();assert_eq!(s.ingest(&changed,false,&c,true,m.occurred_at).unwrap(),Observation::Changed);assert_eq!(s.history().unwrap().len(),1);let d=s.history().unwrap().pop().unwrap();assert_eq!(s.message(&d.message_id).unwrap().unwrap().body,"new");let mut d=d;d.status=Status::InFlight;s.mark(&d).unwrap();changed.body="third".into();changed.id=id();s.ingest(&changed,false,&c,true,m.occurred_at).unwrap();assert_eq!(s.history().unwrap().len(),2);}
#[test] fn failed_ingress_rolls_back_ledger(){let(mut s,c,m)=setup();s.execute("CREATE TRIGGER fail BEFORE INSERT ON deliveries BEGIN SELECT RAISE(ABORT,'test'); END;").unwrap();assert!(s.ingest(&m,false,&c,true,m.occurred_at).is_err());s.execute("DROP TRIGGER fail").unwrap();assert_eq!(s.ingest(&m,false,&c,true,m.occurred_at).unwrap(),Observation::New);}
#[test] fn retention_and_clear_cancel_queue(){let(mut s,c,m)=setup();s.ingest(&m,false,&c,true,m.occurred_at).unwrap();s.purge(m.occurred_at+Duration::days(7)).unwrap();assert_eq!(s.message(&m.id).unwrap().unwrap().body,"");assert_eq!(s.history().unwrap()[0].status,Status::Expired);s.purge(m.occurred_at+Duration::days(30)).unwrap();assert!(s.history().unwrap().is_empty());s.ingest(&Message{source_key:"k2".into(),id:id(),..m.clone()},false,&c,true,m.occurred_at).unwrap();s.clear_history().unwrap();assert!(s.due(Utc::now()).unwrap().is_empty());}
#[test] fn reopening_recovers_inflight_but_readonly_does_not(){let path=std::env::temp_dir().join(format!("notify-native-{}.db",id()));{let mut s=Store::open(&path).unwrap();let(_,c,m)=setup();s.ingest(&m,false,&c,true,m.occurred_at).unwrap();let mut d=s.history().unwrap().pop().unwrap();d.status=Status::InFlight;s.mark(&d).unwrap();}{let s=Store::read_only(&path).unwrap();assert_eq!(s.history().unwrap()[0].status,Status::InFlight);}{let s=Store::open(&path).unwrap();assert_eq!(s.history().unwrap()[0].status,Status::Uncertain);}std::fs::remove_file(path).unwrap();}
